use clap::{Parser, ValueEnum, ArgGroup};
use std::num::NonZeroUsize;

#[derive(Debug, Clone, ValueEnum)]
enum BytesFormat {
    #[value(name = "plain")]
    Plain,
    #[value(name = "metric")]
    Metric,
    #[value(name = "binary")]
    Binary,
}

#[derive(Debug, Clone, ValueEnum)]
enum Quantity {
    #[value(name = "apparent-size")]
    ApparentSize,
    #[value(name = "block-size")]
    BlockSize,
    #[value(name = "block-count")]
    BlockCount,
}

#[derive(Debug, Clone)]
enum MaxDepth {
    Inf,
    Finite(usize),
}

fn parse_max_depth(s: &str) -> Result<MaxDepth, String> {
    if s == "inf" {
        Ok(MaxDepth::Inf)
    } else {
        match s.parse::<NonZeroUsize>() {
            Ok(n) => Ok(MaxDepth::Finite(n.get())),
            Err(e) => Err(format!("Value is neither \"inf\" nor a positive integer: {}", e)),
        }
    }
}

#[derive(Debug, Clone)]
enum Threads {
    Auto,
    Max,
    Count(usize),
}

fn parse_threads(s: &str) -> Result<Threads, String> {
    if s == "auto" {
        Ok(Threads::Auto)
    } else if s == "max" {
        Ok(Threads::Max)
    } else {
        match s.parse::<NonZeroUsize>() {
            Ok(n) => Ok(Threads::Count(n.get())),
            Err(e) => Err(format!("Value is neither \"auto\", \"max\", nor a number: {}", e)),
        }
    }
}

fn parse_min_ratio(s: &str) -> Result<f64, String> {
    match s.parse::<f64>() {
        Ok(v) => {
            if v < 0.0 {
                Err("less than 0".to_string())
            } else if v >= 1.0 {
                Err("greater than or equal to 1".to_string())
            } else {
                Ok(v)
            }
        }
        Err(_) => Err("invalid float literal".to_string()),
    }
}

#[derive(Parser, Debug)]
