    #[arg(short = 'd', long = "max-depth", alias = "depth", default_value = "10", value_parser = parse_max_depth)]
    max_depth: MaxDepth,

    #[arg(short = 'w', long = "total-width", aliases = ["width"], conflicts_with = "column_width")]
    total_width: Option<usize>,

    #[arg(long = "column-width", num_args = 2, value_names = ["TREE_WIDTH", "BAR_WIDTH"], conflicts_with = "total_width")]
    column_width: Option<Vec<usize>>,

    #[arg(short = 'm', long = "min-ratio", default_value = "0.01", value_parser = parse_min_ratio)]
    min_ratio: f64,

    #[arg(long = "no-sort")]
    no_sort: bool,

    #[arg(short = 's', long = "silent-errors", aliases = ["no-errors"])]
    silent_errors: bool,

    #[arg(short = 'p', long = "progress")]
