                .help("Detect and subtract the sizes of hardlinks from their parent directory totals")
        )
        .arg(
            Arg::new("top_down")
                .long("top-down")
                .action(ArgAction::SetTrue)
                .help("Print the tree top-down instead of bottom-up")
        )
        .arg(
            Arg::new("align_right")
                .long("align-right")
                .action(ArgAction::SetTrue)
                .help("Set the root of the bars to the right")
        )
        .arg(
