                .short('q')
                .long("quantity")
                .value_name("QUANTITY")
                .default_value("block-size")
                .value_parser(["apparent-size", "block-size", "block-count"])
                .help("Aspect of the files/directories to be measured")
                .long_help("Aspect of the files/directories to be measured\n\nPossible values:\n- apparent-size: Measure apparent sizes\n- block-size:    Measure block sizes (block-count * 512B)\n- block-count:   Count numbers of blocks")
        )
        .arg(
