                .help("Maximum depth to display the data. Could be either \"inf\" or a positive integer")
        )
        .arg(
            Arg::new("total_width")
                .short('w')
                .long("total-width")
                .alias("width")
                .value_name("TOTAL_WIDTH")
                .conflicts_with("column_width")
