fn format_metric(size: u64) -> String {
    if size < 1000 {
        return size.to_string();
    }
    let units = ["", "K", "M", "G", "T", "P", "E"];
    let mut val = size as f64;
    let mut unit_idx = 0;
    while val >= 1000.0 && unit_idx < units.len() - 1 {
        val /= 1000.0;
        unit_idx += 1;
    }
    // Now format with one decimal, but if <10 maybe one decimal? From earlier examples: 1000 => 1.0K, 1024 =>1.0K, 10240 =>10.2K? Wait 10240 metric => 10.2K (10240/1000=10.24 =>10.2K). 10000 =>10.0K. So one decimal.
    // For values >=1000 after division? Actually we already divided.
    // Format: if val < 10, one decimal? But we saw 1.0K, 10.0K, 100.0K, 1000.0K, 1.0M etc. So always one decimal when using units?
    // For size exactly 1000, val=1.0 => "1.0K"
    // For size 999, val 999 <1000 => "999" plain.
    // So for unit_idx>0, format with one decimal: "{:.1}{unit}"
    format!("{:.1}{}", val, units[unit_idx])
}

fn format_binary(size: u64) -> String {
    if size < 1024 {
        return size.to_string();
    }
    let units = ["", "K", "M", "G", "T", "P", "E"];
    let mut val = size as f64;
    let mut unit_idx = 0;
    while val >= 1024.0 && unit_idx < units.len() - 1 {
        val /= 1024.0;
        unit_idx += 1;
    }
    // For binary, threshold 1024, format with one decimal, but for bytes <1024 plain.
    // Edge: we saw 1023 => "1023", 1024 => "1.0K", 10239 => "10.0K", 10240 => "10.0K", 1048575 => "1024.0K", 1048576 => "1.0M"
    // So same as metric but base 1024.
    format!("{:.1}{}", val, units[unit_idx])
}

fn sort_tree_by_size(mut node: TreeNode) -> TreeNode {
    // Recursively sort children by size descending, stable
    for child in &mut node.children {
        *child = sort_tree_by_size(child.clone());
    }
    // Sort children by size descending, stable
    // Use stable sort
    node.children.sort_by(|a, b| b.size.cmp(&a.size));
    node
}

