    nlink: u64,
    paths: Vec<String>,
    dev: u64,
    ino: u64,
}

struct ErrorReporter {
    silent: bool,
    errors: Arc<Mutex<Vec<String>>>,
}

impl ErrorReporter {
    fn new(silent: bool) -> Self {
        Self {
            silent,
            errors: Arc::new(Mutex::new(Vec::new())),
        }
    }
    fn report(&self, op: &str, path: &str, err: &std::io::Error) {
        if self.silent {
            return;
        }
        let msg = format!("[error] {} \"{}\": {}", op, path, err);
        let mut guard = self.errors.lock().unwrap();
        guard.push(msg);
    }
    fn get_errors(&self) -> Vec<String> {
        self.errors.lock().unwrap().clone()
    }
}

// Determine if metadata corresponds to a directory (following lstat, so symlink is not dir)
fn is_dir_meta(meta: &fs::Metadata) -> bool {
    meta.file_type().is_dir()
}

fn quantity_size(meta: &fs::Metadata, q: Quantity) -> u64 {
    match q {
        Quantity::ApparentSize => meta.len(),
        Quantity::BlockSize => meta.blocks() * 512,
        Quantity::BlockCount => meta.blocks(),
    }
}

// Build a BuildNode for a given path string (as provided by user, may not exist)
fn build_for_path(
    input_path_str: &str,
    quantity: Quantity,
    dedup: bool,
    error_reporter: &ErrorReporter,
    global_hardlinks: &Arc<Mutex<HashMap<(u64, u64), HardlinkInfo>>>,
) -> BuildNode {
    let path = Path::new(input_path_str);
    match fs::symlink_metadata(path) {
        Err(e) => {
            error_reporter.report("symlink_metadata", input_path_str, &e);
            // size 0, no children, empty sets
            BuildNode {
                name: input_path_str.to_string(),
                size: 0,
                children: Vec::new(),
                inodes_set: HashSet::new(),
                inode_sizes: HashMap::new(),
                own_size: 0,
            }
        }
        Ok(meta) => {
            let own_size = quantity_size(&meta, quantity);
            if is_dir_meta(&meta) {
                // Directory: read entries
                let mut children = Vec::new();
                let mut total_inodes_set = HashSet::new();
                let mut total_inode_sizes: HashMap<(u64, u64), u64> = HashMap::new();
                let mut total_size = own_size;

                match fs::read_dir(path) {
                    Err(e) => {
                        error_reporter.report("read_dir", input_path_str, &e);
                    }
                    Ok(rd) => {
                        for entry_res in rd {
                            match entry_res {
                                Err(e) => {
                                    // What operation for entry error? Probably read_dir as well? But we treat as read_dir?
                                    // For simplicity, report as read_dir with path of parent? But original only reports read_dir for parent path.
                                    // Let's report read_dir for the parent path with the error.
                                    error_reporter.report("read_dir", input_path_str, &e);
                                }
                                Ok(entry) => {
                                    let entry_path = entry.path();
                                    let entry_name_os = entry.file_name();
                                    let entry_name = entry_name_os.to_string_lossy().to_string();
                                    let entry_path_str = entry_path.to_string_lossy().to_string();

                                    // Need to get symlink_metadata for entry
                                    match fs::symlink_metadata(&entry_path) {
                                        Err(e) => {
                                            error_reporter.report("symlink_metadata", &entry_path_str, &e);
                                            // create child with size 0
                                            let child = BuildNode {
                                                name: entry_name,
                                                size: 0,
                                                children: Vec::new(),
                                                inodes_set: HashSet::new(),
                                                inode_sizes: HashMap::new(),
                                                own_size: 0,
                                            };
                                            total_size += child.size;
                                            // merge inodes (none)
                                            // no inode to merge
                                            children.push(child);
                                        }
                                        Ok(child_meta) => {
                                            let child_own_size = quantity_size(&child_meta, quantity);
                                            // Check if hardlink file
                                            let mut child_inodes_set = HashSet::new();
                                            let mut child_inode_sizes = HashMap::new();
                                            let mut child_total_size;
                                            let mut child_children = Vec::new();

                                            if is_dir_meta(&child_meta) {
                                                // Recursively build for directory child
                                                // For recursion, we need to call a helper that builds subtree for this child path
                                                let sub_node = build_recursive(
                                                    &entry_path,
                                                    entry_name.clone(),
                                                    quantity,
                                                    dedup,
                                                    error_reporter,
                                                    global_hardlinks,
                                                );
                                                // sub_node already computed
                                                child_total_size = sub_node.size;
                                                child_inodes_set = sub_node.inodes_set;
                                                child_inode_sizes = sub_node.inode_sizes;
                                                child_children = sub_node.children;
                                            } else {
                                                // File (or symlink, etc.)
                                                child_total_size = child_own_size;
                                                if dedup && child_meta.nlink() > 1 {
                                                    let key = (child_meta.dev(), child_meta.ino());
                                                    let info_size = child_own_size;
                                                    child_inodes_set.insert(key);
                                                    child_inode_sizes.insert(key, info_size);
                                                    // Record globally for shared reporting
                                                    {
                                                        let mut guard = global_hardlinks.lock().unwrap();
                                                        let entry = guard.entry(key).or_insert_with(|| HardlinkInfo {
                                                            size: info_size,
                                                            nlink: child_meta.nlink(),
                                                            paths: Vec::new(),
                                                            dev: key.0,
                                                            ino: key.1,
                                                        });
                                                        // Update size if needed? Keep first size? But size should be same; use current
                                                        entry.size = info_size;
                                                        entry.nlink = child_meta.nlink();
                                                        entry.paths.push(entry_path_str.clone());
                                                    }
                                                }
                                            }

                                            // Merge into parent total
                                            // For dedup mode, we need to handle duplicate inodes across children
                                            if dedup {
                                                // For each inode in child, check if already seen in total_inodes_set
                                                let mut dup_size_to_subtract = 0u64;
                                                for inode_key in &child_inodes_set {
                                                    if total_inodes_set.contains(inode_key) {
                                                        // duplicate across children -> subtract its size
                                                        if let Some(sz) = child_inode_sizes.get(inode_key).or_else(|| total_inode_sizes.get(inode_key)) {
                                                            dup_size_to_subtract += *sz;
                                                        } else if let Some(sz) = total_inode_sizes.get(inode_key) {
                                                            dup_size_to_subtract += *sz;
                                                        }
                                                    }
                                                }
                                                total_size += child_total_size;
                                                total_size = total_size.saturating_sub(dup_size_to_subtract);
                                                // Merge sets
                                                for k in child_inodes_set.iter() {
                                                    total_inodes_set.insert(*k);
                                                }
                                                for (k, v) in child_inode_sizes {
                                                    total_inode_sizes.entry(k).or_insert(v);
                                                }
                                            } else {
                                                total_size += child_total_size;
                                            }

                                            let child_node = BuildNode {
                                                name: entry_name,
                                                size: child_total_size,
                                                children: child_children,
                                                inodes_set: child_inodes_set,
                                                inode_sizes: child_inode_sizes,
                                                own_size: child_own_size,
                                            };
                                            children.push(child_node);
                                        }
                                    }
                                }
                            }
                        }
                    }
                }

                BuildNode {
                    name: input_path_str.to_string(),
                    size: total_size,
                    children,
                    inodes_set: total_inodes_set,
                    inode_sizes: total_inode_sizes,
                    own_size,
                }
            } else {
                // File
                let mut inodes_set = HashSet::new();
                let mut inode_sizes = HashMap::new();
                if dedup && meta.nlink() > 1 {
                    let key = (meta.dev(), meta.ino());
                    inodes_set.insert(key);
                    inode_sizes.insert(key, own_size);
                    {
                        let mut guard = global_hardlinks.lock().unwrap();
                        let entry = guard.entry(key).or_insert_with(|| HardlinkInfo {
                            size: own_size,
                            nlink: meta.nlink(),
                            paths: Vec::new(),
                            dev: key.0,
                            ino: key.1,
                        });
                        entry.size = own_size;
                        entry.nlink = meta.nlink();
                        entry.paths.push(input_path_str.to_string());
                    }
                }
                BuildNode {
                    name: input_path_str.to_string(),
                    size: own_size,
                    children: Vec::new(),
                    inodes_set,
                    inode_sizes,
                    own_size,
                }
            }
        }
    }
}

fn build_recursive(
    path: &Path,
    name: String,
    quantity: Quantity,
    dedup: bool,
    error_reporter: &ErrorReporter,
    global_hardlinks: &Arc<Mutex<HashMap<(u64, u64), HardlinkInfo>>>,
) -> BuildNode {
    let path_str = path.to_string_lossy().to_string();
    // symlink_metadata already done in caller? But we can redo to get meta; but we already have own_size logic inside loop? Let's directly handle directory recursion:
    // This function is called only for directories
    let meta = match fs::symlink_metadata(path) {
        Err(e) => {
            error_reporter.report("symlink_metadata", &path_str, &e);
            return BuildNode {
                name,
                size: 0,
                children: Vec::new(),
                inodes_set: HashSet::new(),
                inode_sizes: HashMap::new(),
                own_size: 0,
            };
        }
        Ok(m) => m,
    };
    let own_size = quantity_size(&meta, quantity);
    let mut children = Vec::new();
    let mut total_inodes_set = HashSet::new();
    let mut total_inode_sizes = HashMap::new();
    let mut total_size = own_size;

    match fs::read_dir(path) {
        Err(e) => {
            error_reporter.report("read_dir", &path_str, &e);
        }
        Ok(rd) => {
            for entry_res in rd {
                match entry_res {
                    Err(e) => {
                        error_reporter.report("read_dir", &path_str, &e);
                    }
                    Ok(entry) => {
                        let entry_path = entry.path();
                        let entry_name = entry.file_name().to_string_lossy().to_string();
                        let entry_path_str = entry_path.to_string_lossy().to_string();

                        match fs::symlink_metadata(&entry_path) {
                            Err(e) => {
                                error_reporter.report("symlink_metadata", &entry_path_str, &e);
                                let child = BuildNode {
                                    name: entry_name,
                                    size: 0,
                                    children: Vec::new(),
                                    inodes_set: HashSet::new(),
                                    inode_sizes: HashMap::new(),
                                    own_size: 0,
                                };
                                total_size += child.size;
                                children.push(child);
                            }
                            Ok(child_meta) => {
                                let child_own_size = quantity_size(&child_meta, quantity);
                                if is_dir_meta(&child_meta) {
                                    let sub_node = build_recursive(
                                        &entry_path,
                                        entry_name.clone(),
                                        quantity,
                                        dedup,
                                        error_reporter,
                                        global_hardlinks,
                                    );
                                    if dedup {
                                        let mut dup = 0u64;
                                        for inode_key in &sub_node.inodes_set {
                                            if total_inodes_set.contains(inode_key) {
                                                if let Some(sz) = sub_node.inode_sizes.get(inode_key).or_else(|| total_inode_sizes.get(inode_key)) {
                                                    dup += *sz;
                                                }
                                            }
                                        }
                                        total_size += sub_node.size;
                                        total_size = total_size.saturating_sub(dup);
                                        for k in &sub_node.inodes_set {
                                            total_inodes_set.insert(*k);
                                        }
                                        for (k, v) in &sub_node.inode_sizes {
                                            total_inode_sizes.entry(*k).or_insert(*v);
                                        }
                                    } else {
                                        total_size += sub_node.size;
                                    }
                                    children.push(sub_node);
                                } else {
                                    let mut child_inodes_set = HashSet::new();
                                    let mut child_inode_sizes = HashMap::new();
                                    let child_total_size = child_own_size;
                                    if dedup && child_meta.nlink() > 1 {
                                        let key = (child_meta.dev(), child_meta.ino());
                                        child_inodes_set.insert(key);
                                        child_inode_sizes.insert(key, child_own_size);
                                        {
                                            let mut guard = global_hardlinks.lock().unwrap();
                                            let entry = guard.entry(key).or_insert_with(|| HardlinkInfo {
                                                size: child_own_size,
                                                nlink: child_meta.nlink(),
                                                paths: Vec::new(),
                                                dev: key.0,
                                                ino: key.1,
                                            });
                                            entry.size = child_own_size;
                                            entry.nlink = child_meta.nlink();
                                            entry.paths.push(entry_path_str.clone());
                                        }
                                    }

                                    if dedup {
                                        let mut dup = 0u64;
                                        for inode_key in &child_inodes_set {
                                            if total_inodes_set.contains(inode_key) {
                                                if let Some(sz) = child_inode_sizes.get(inode_key) {
                                                    dup += *sz;
                                                }
                                            }
                                        }
                                        total_size += child_total_size;
                                        total_size = total_size.saturating_sub(dup);
                                        for k in &child_inodes_set {
                                            total_inodes_set.insert(*k);
                                        }
                                        for (k, v) in child_inode_sizes {
                                            total_inode_sizes.entry(k).or_insert(v);
                                        }
                                    } else {
                                        total_size += child_total_size;
                                    }

                                    let child_node = BuildNode {
                                        name: entry_name,
                                        size: child_total_size,
                                        children: Vec::new(),
                                        inodes_set: child_inodes_set,
                                        inode_sizes: child_inode_sizes,
                                        own_size: child_own_size,
                                    };
                                    children.push(child_node);
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    BuildNode {
        name,
        size: total_size,
        children,
        inodes_set: total_inodes_set,
        inode_sizes: total_inode_sizes,
        own_size,
    }
}

// For multiple inputs, we need to create a virtual root if more than one
fn build_forest(
    inputs: &[String],
    quantity: Quantity,
    dedup: bool,
    error_reporter: &ErrorReporter,
) -> (BuildNode, HashMap<(u64, u64), HardlinkInfo>) {
    let global_hardlinks: Arc<Mutex<HashMap<(u64, u64), HardlinkInfo>>> = Arc::new(Mutex::new(HashMap::new()));

    if inputs.is_empty() {
        // use current dir "."
        let node = build_for_path(".", quantity, dedup, error_reporter, &global_hardlinks);
        let map = global_hardlinks.lock().unwrap().clone();
        (node, map)
    } else if inputs.len() == 1 {
        let node = build_for_path(&inputs[0], quantity, dedup, error_reporter, &global_hardlinks);
        let map = global_hardlinks.lock().unwrap().clone();
        (node, map)
    } else {
        // multiple
        let mut children = Vec::new();
        let mut total_inodes_set = HashSet::new();
        let mut total_inode_sizes = HashMap::new();
        let mut total_size = 0u64; // own size 0 for virtual root

        for input in inputs {
            let child = build_for_path(input, quantity, dedup, error_reporter, &global_hardlinks);
            if dedup {
                let mut dup = 0u64;
                for inode_key in &child.inodes_set {
                    if total_inodes_set.contains(inode_key) {
                        if let Some(sz) = child.inode_sizes.get(inode_key).or_else(|| total_inode_sizes.get(inode_key)) {
                            dup += *sz;
                        }
                    }
                }
                total_size += child.size;
                total_size = total_size.saturating_sub(dup);
                for k in &child.inodes_set {
                    total_inodes_set.insert(*k);
                }
                for (k, v) in &child.inode_sizes {
                    total_inode_sizes.entry(*k).or_insert(*v);
                }
            } else {
                total_size += child.size;
            }
            children.push(child);
        }

        let root = BuildNode {
            name: "(total)".to_string(),
            size: total_size,
            children,
            inodes_set: total_inodes_set,
            inode_sizes: total_inode_sizes,
            own_size: 0,
        };
        let map = global_hardlinks.lock().unwrap().clone();
        (root, map)
    }
}

fn buildnode_to_treenode(b: &BuildNode, no_sort: bool) -> TreeNode {
    // Convert, sorting children if needed
    let mut children: Vec<TreeNode> = b.children.iter().map(|c| buildnode_to_treenode(c, no_sort)).collect();
    if !no_sort {
        // sort by size descending, but original's order for equal sizes seems not alphabetical? However we need deterministic.
        // From earlier tests: for different sizes, descending. For equal sizes, seems to preserve filesystem order? But we saw equal sizes gave order based on filesystem? Let's test: for equal sizes, no-sort and sorted gave same (filesystem) order? In earlier test equal sizes with a,b,c creation order gave sorted order a,b,c (same as filesystem). For z,a,m case, sorted gave order same as filesystem order (z,a,m) not alphabetical. So sorting by size descending, and when equal, maybe stable sort preserving original order? That is plausible.
        // So we should sort by size descending, stable.
        children.sort_by(|a, b| b.size.cmp(&a.size));
        // Actually stable sort: use sort_by with b.size vs a.size, but stable keeps original order for equal.
        // However we previously saw for block-size equal 0 case, sorted order preserved filesystem order (z,a,m). So stable descending.
    }
    TreeNode {
        name: b.name.clone(),
        size: b.size,
        children,
    }
}

fn main() {
    // First, handle custom error messages before clap? We need to implement CLI parsing manually to match original behavior for some edge cases.
    // We'll parse using clap_builder.

    // Build command
    let cmd = build_cli_command();

    // Use try_get_matches to capture errors and also handle version/help manually? clap handles.
    let matches = match cmd.try_get_matches() {
        Ok(m) => m,
        Err(e) => {
            // clap errors should be printed to stderr and exit with code 2? Original does that.
            e.exit();
        }
    };

    // Extract flags
    let json_input = matches.get_flag("json_input");
    let json_output = matches.get_flag("json_output");
    let deduplicate = matches.get_flag("deduplicate_hardlinks");
    let top_down = matches.get_flag("top_down");
    let align_right = matches.get_flag("align_right");
    let no_sort = matches.get_flag("no_sort");
    let silent_errors = matches.get_flag("silent_errors");
    let progress = matches.get_flag("progress");
    let omit_details = matches.get_flag("omit_json_shared_details");
    let omit_summary = matches.get_flag("omit_json_shared_summary");

    let bytes_format_str = matches.get_one::<String>("bytes_format").unwrap().as_str();
    let bytes_format = match bytes_format_str {
        "plain" => BytesFormat::Plain,
        "metric" => BytesFormat::Metric,
        "binary" => BytesFormat::Binary,
        _ => BytesFormat::Metric,
    };

    let quantity_str = matches.get_one::<String>("quantity").unwrap().as_str();
    let quantity = match quantity_str {
        "apparent-size" => Quantity::ApparentSize,
        "block-size" => Quantity::BlockSize,
        "block-count" => Quantity::BlockCount,
        _ => Quantity::BlockSize,
    };

    let max_depth_str = matches.get_one::<String>("max_depth").unwrap().as_str();
    let max_depth = match parse_max_depth(max_depth_str) {
        Ok(md) => md,
        Err(msg) => {
            eprintln!("error: invalid value '{}' for '--max-depth <MAX_DEPTH>': {}", max_depth_str, msg);
            eprintln!();
            eprintln!("For more information, try '--help'.");
            std::process::exit(2);
        }
    };

    let total_width = match matches.get_one::<String>("total_width") {
        Some(s) => {
            match parse_total_width(s) {
                Ok(v) => Some(v),
                Err(msg) => {
                    eprintln!("error: invalid value '{}' for '--total-width <TOTAL_WIDTH>': {}", s, msg);
                    eprintln!();
                    eprintln!("For more information, try '--help'.");
                    std::process::exit(2);
                }
            }
        }
        None => None,
    };

    let column_width = match matches.get_many::<String>("column_width") {
        Some(vals) => {
            let vec: Vec<String> = vals.cloned().collect();
            if vec.len() != 2 {
                // Should be handled by clap num_args, but in case of duplicate values causing 4, we replicate original panic behavior?
                // Original panics with src/args.rs debug. We will mimic error: print debug and panic? However for simplicity, we will error with same message as clap's "2 values required" if len!=2?
                // Actually clap's num_args=2 ensures exactly 2 per occurrence. If duplicate occurrence, vec len 4. Original code had bug.
                // To match original's panic for that specific case, we could panic similar.
                if vec.len() == 4 {
                    // Mimic original panic output: it printed total_width and column_width debug
                    let total_width_dbg = if let Some(tw) = &total_width { format!("Some({})", tw) } else { "None".to_string() };
                    eprintln!("[src/args.rs:191:17] total_width = {}", total_width_dbg);
                    eprintln!("[src/args.rs:191:17] column_width = Some(");
                    eprintln!("    [");
                    for v in &vec {
                        eprintln!("        {},", v);
                    }
                    eprintln!("    ],");
                    eprintln!(")");
                    eprintln!();
