            //   * Number of shared inodes: 1
            //   * Total number of links: 2
            //   * Total shared size: 4.1K
            // Case all have outside:
            //   "Hardlinks detected! All hardlinks within this tree have links without"
            //   * Number of shared inodes: 1
            //   * Total number of links: 2 total, 1 detected
            //   * Total shared size: 4.1K
            //   OR with numbers:
            //   * Number of shared inodes: 1
            //   * Total number of links: 3 total, 2 detected
            //   * Total shared size: 4.1K
            // For mixed:
            //   "Hardlinks detected! Some files have links outside this tree"
            //   * Number of shared inodes: 2 total, 1 exclusive
            //   * Total number of links: 4 total, 3 detected, 2 exclusive
            //   * Total shared size: 8.2K total, 4.1K exclusive

            // Need to format sizes using bytes_format
            // Also need to determine which variant to use:
            // - If exclusive_inodes == inodes (all exclusive) => No files have links outside
            // - Else if exclusive_inodes == 0 (none exclusive) => All hardlinks within this tree have links without
            // - Else => Some files have links outside

            let formatted_shared_size = format_size(shared_size, bytes_format, quantity);
            let formatted_exclusive_shared_size = format_size(exclusive_shared_size, bytes_format, quantity);

            if exclusive_inodes == inodes {
