}

fn build_cli_command() -> Command {
    Command::new("pdu")
        .version("0.21.1")
        .about("Summarize disk usage of the set of files, recursively for directories.")
        .long_about("Summarize disk usage of the set of files, recursively for directories.\n\nCopyright: Apache-2.0 © 2021 Hoàng Văn Khải <https://github.com/KSXGitHub/>\nSponsor: https://github.com/sponsors/KSXGitHub")
        .after_long_help("Examples:\n    Show disk usage chart of current working directory\n    $ pdu\n\n    Show disk usage chart of a single file or directory\n    $ pdu path/to/file/or/directory\n\n    Compare disk usages of multiple files and/or directories\n    $ pdu file.txt dir/\n\n    Show chart in apparent sizes instead of block sizes\n    $ pdu --quantity=apparent-size\n\n    Detect and subtract the sizes of hardlinks from their parent nodes\n    $ pdu --deduplicate-hardlinks\n\n    Show sizes in plain numbers instead of metric units\n    $ pdu --bytes-format=plain\n\n    Show sizes in base 2¹⁰ units (binary) instead of base 10³ units (metric)\n    $ pdu --bytes-format=binary\n\n    Show disk usage chart of all entries regardless of size\n    $ pdu --min-ratio=0\n\n    Only show disk usage chart of entries whose size is at least 5% of total\n    $ pdu --min-ratio=0.05\n\n    Show disk usage data as JSON instead of chart\n    $ pdu --min-ratio=0 --max-depth=inf --json-output | jq\n\n    Visualize existing JSON representation of disk usage data\n    $ pdu --json-input < disk-usage.json")
        .arg(
            Arg::new("json_input")
                .long("json-input")
                .action(ArgAction::SetTrue)
                .help("Read JSON data from stdin")
                .conflicts_with_all(["quantity", "deduplicate_hardlinks"])
        )
        .arg(
            Arg::new("json_output")
                .long("json-output")
                .action(ArgAction::SetTrue)
                .help("Print JSON data instead of an ASCII chart")
        )
        .arg(
            Arg::new("bytes_format")
                .short('b')
                .long("bytes-format")
                .value_name("BYTES_FORMAT")
                .default_value("metric")
                .value_parser(["plain", "metric", "binary"])
                .help("How to display the numbers of bytes")
                .long_help("How to display the numbers of bytes\n\nPossible values:\n- plain:  Display plain number of bytes without units\n- metric: Use metric scale, i.e. 1K = 1000B, 1M = 1000K, and so on\n- binary: Use binary scale, i.e. 1K = 1024B, 1M = 1024K, and so on")
        )
        .arg(
            Arg::new("deduplicate_hardlinks")
                .short('H')
                .long("deduplicate-hardlinks")
                .aliases(["detect-links", "dedupe-links"])
                .action(ArgAction::SetTrue)
                .help("Detect and subtract the sizes of hardlinks from their parent directory totals")
        )
        .arg(
            Arg::new("top_down")
                .long("top-down")
                .action(ArgAction::SetTrue)
                .help("Print the tree top-down instead of bottom-up")
        )
        .arg(
            Arg::new("align_right")
                .long("align-right")
                .action(ArgAction::SetTrue)
                .help("Set the root of the bars to the right")
        )
        .arg(
            Arg::new("quantity")
                .short('q')
                .long("quantity")
                .value_name("QUANTITY")
                .default_value("block-size")
                .value_parser(["apparent-size", "block-size", "block-count"])
                .help("Aspect of the files/directories to be measured")
                .long_help("Aspect of the files/directories to be measured\n\nPossible values:\n- apparent-size: Measure apparent sizes\n- block-size:    Measure block sizes (block-count * 512B)\n- block-count:   Count numbers of blocks")
        )
        .arg(
            Arg::new("max_depth")
                .short('d')
                .long("max-depth")
                .alias("depth")
                .value_name("MAX_DEPTH")
                .default_value("10")
                .help("Maximum depth to display the data. Could be either \"inf\" or a positive integer")
        )
        .arg(
            Arg::new("total_width")
                .short('w')
                .long("total-width")
                .alias("width")
                .value_name("TOTAL_WIDTH")
                .conflicts_with("column_width")
                .help("Width of the visualization")
        )
        .arg(
            Arg::new("column_width")
                .long("column-width")
                .value_names(["TREE_WIDTH", "BAR_WIDTH"])
                .num_args(2)
                .conflicts_with("total_width")
                .help("Maximum widths of the tree column and width of the bar column")
        )
        .arg(
            Arg::new("min_ratio")
                .short('m')
                .long("min-ratio")
                .value_name("MIN_RATIO")
                .default_value("0.01")
                .help("Minimal size proportion required to appear")
        )
        .arg(
            Arg::new("no_sort")
                .long("no-sort")
                .action(ArgAction::SetTrue)
                .help("Do not sort the branches in the tree")
        )
        .arg(
            Arg::new("silent_errors")
                .short('s')
                .long("silent-errors")
                .alias("no-errors")
                .action(ArgAction::SetTrue)
                .help("Prevent filesystem error messages from appearing in stderr")
        )
        .arg(
            Arg::new("progress")
                .short('p')
                .long("progress")
                .action(ArgAction::SetTrue)
                .help("Report progress being made at the expense of performance")
        )
        .arg(
            Arg::new("threads")
                .long("threads")
                .value_name("THREADS")
                .default_value("auto")
                .help("Set the maximum number of threads to spawn. Could be either \"auto\", \"max\", or a positive integer")
        )
        .arg(
            Arg::new("omit_json_shared_details")
                .long("omit-json-shared-details")
                .action(ArgAction::SetTrue)
                .help("Do not output `.shared.details` in the JSON output")
                .requires_all(["json_output", "deduplicate_hardlinks"])
        )
        .arg(
            Arg::new("omit_json_shared_summary")
                .long("omit-json-shared-summary")
                .action(ArgAction::SetTrue)
                .help("Do not output `.shared.summary` in the JSON output")
                .requires_all(["json_output", "deduplicate_hardlinks"])
        )
        .arg(
            Arg::new("files")
                .value_name("FILES")
                .num_args(0..)
                .value_hint(ValueHint::AnyPath)
                .help("List of files and/or directories")
        )
}

fn get_terminal_width(total_width: Option<usize>, column_width: Option<&Vec<usize>>) -> usize {
    // If total_width or column_width provided, terminal width detection may be irrelevant? But original still uses COLUMNS? Let's see: when total_width provided, it overrides? For our implementation, we will compute based on total_width or column_width + other columns, but we also need default terminal width.
    // Original behavior: total_width overrides COLUMNS? From test, with COLUMNS=200 and --total-width=50, line length was 50. So total_width overrides.
