        } else { None };
        let json_root = JsonRoot { schema_version: SCHEMA_VERSION.to_string(), pdu: PDU_VERSION.to_string(), unit: unit_str.to_string(), tree: tree_node, shared };
        let json_str = serde_json::to_string(&json_root).unwrap();
        println!("{}", json_str);
        let errors = error_reporter.get_errors();
        eprint!("\r\r");
        for err in errors { eprintln!("{}", err); eprint!("\r\r"); }
        std::process::exit(0);
    } else {
        let term_width = get_terminal_width(total_width, column_width.as_ref());
        let visualizer = Visualizer {
            bytes_format,
            top_down,
            align_right,
            max_depth: match max_depth { MaxDepth::Inf => usize::MAX, MaxDepth::Finite(d) => d },
            min_ratio,
            no_sort,
