    size: u64,
    children: Vec<BuildNode>,
    inodes_set: HashSet<(u64, u64)>,
    inode_sizes: HashMap<(u64, u64), u64>,
    own_size: u64,
}

#[derive(Debug, Clone)]
struct HardlinkInfo { size: u64, nlink: u64, paths: Vec<String>, dev: u64, ino: u64 }

struct ErrorReporter { silent: bool, errors: Arc<Mutex<Vec<String>>> }
impl ErrorReporter {
    fn new(silent: bool) -> Self { Self { silent, errors: Arc::new(Mutex::new(Vec::new())) } }
    fn report(&self, op: &str, path: &str, err: &std::io::Error) {
        if self.silent { return; }
        let msg = format!("[error] {} \"{}\": {}", op, path, err);
        let mut guard = self.errors.lock().unwrap();
        guard.push(msg);
    }
    fn get_errors(&self) -> Vec<String> { self.errors.lock().unwrap().clone() }
}

fn is_dir_meta(meta: &fs::Metadata) -> bool { meta.file_type().is_dir() }
fn quantity_size(meta: &fs::Metadata, q: Quantity) -> u64 {
    match q {
        Quantity::ApparentSize => meta.len(),
        Quantity::BlockSize => meta.blocks() * 512,
        Quantity::BlockCount => meta.blocks(),
    }
}

fn build_recursive(path: &Path, name: String, quantity: Quantity, dedup: bool, error_reporter: &ErrorReporter, global_hardlinks: &Arc<Mutex<HashMap<(u64, u64), HardlinkInfo>>>) -> BuildNode {
    let path_str = path.to_string_lossy().to_string();
    let meta = match fs::symlink_metadata(path) {
        Err(e) => {
            error_reporter.report("symlink_metadata", &path_str, &e);
            return BuildNode { name, size: 0, children: Vec::new(), inodes_set: HashSet::new(), inode_sizes: HashMap::new(), own_size: 0 };
        }
        Ok(m) => m,
    };
    let own_size = quantity_size(&meta, quantity);
    if !is_dir_meta(&meta) {
        let mut inodes_set = HashSet::new();
        let mut inode_sizes = HashMap::new();
        if dedup && meta.nlink() > 1 {
            let key = (meta.dev(), meta.ino());
            inodes_set.insert(key);
            inode_sizes.insert(key, own_size);
            let mut guard = global_hardlinks.lock().unwrap();
            let entry = guard.entry(key).or_insert_with(|| HardlinkInfo { size: own_size, nlink: meta.nlink(), paths: Vec::new(), dev: key.0, ino: key.1 });
            entry.size = own_size;
            entry.nlink = meta.nlink();
            entry.paths.push(path_str.clone());
        }
        return BuildNode { name, size: own_size, children: Vec::new(), inodes_set, inode_sizes, own_size };
    }
    let mut children = Vec::new();
    let mut total_inodes_set = HashSet::new();
    let mut total_inode_sizes = HashMap::new();
    let mut total_size = own_size;
    match fs::read_dir(path) {
        Err(e) => { error_reporter.report("read_dir", &path_str, &e); }
        Ok(rd) => {
            for entry_res in rd {
                match entry_res {
                    Err(e) => { error_reporter.report("read_dir", &path_str, &e); }
                    Ok(entry) => {
                        let entry_path = entry.path();
                        let entry_name = entry.file_name().to_string_lossy().to_string();
                        let entry_path_str = entry_path.to_string_lossy().to_string();
                        match fs::symlink_metadata(&entry_path) {
                            Err(e) => {
                                error_reporter.report("symlink_metadata", &entry_path_str, &e);
                                let child = BuildNode { name: entry_name, size: 0, children: Vec::new(), inodes_set: HashSet::new(), inode_sizes: HashMap::new(), own_size: 0 };
                                total_size += child.size;
                                children.push(child);
                            }
                            Ok(child_meta) => {
                                if is_dir_meta(&child_meta) {
                                    let sub_node = build_recursive(&entry_path, entry_name.clone(), quantity, dedup, error_reporter, global_hardlinks);
                                    if dedup {
                                        let mut dup = 0u64;
                                        for inode_key in &sub_node.inodes_set {
                                            if total_inodes_set.contains(inode_key) {
                                                if let Some(sz) = sub_node.inode_sizes.get(inode_key).or_else(|| total_inode_sizes.get(inode_key)) { dup += *sz; }
                                            }
                                        }
                                        total_size += sub_node.size;
                                        total_size = total_size.saturating_sub(dup);
                                        for k in &sub_node.inodes_set { total_inodes_set.insert(*k); }
                                        for (k,v) in &sub_node.inode_sizes { total_inode_sizes.entry(*k).or_insert(*v); }
                                    } else { total_size += sub_node.size; }
                                    children.push(sub_node);
                                } else {
                                    let child_own_size = quantity_size(&child_meta, quantity);
                                    let mut child_inodes_set = HashSet::new();
                                    let mut child_inode_sizes = HashMap::new();
                                    let child_total_size = child_own_size;
                                    if dedup && child_meta.nlink() > 1 {
                                        let key = (child_meta.dev(), child_meta.ino());
                                        child_inodes_set.insert(key);
                                        child_inode_sizes.insert(key, child_own_size);
                                        let mut guard = global_hardlinks.lock().unwrap();
                                        let entry = guard.entry(key).or_insert_with(|| HardlinkInfo { size: child_own_size, nlink: child_meta.nlink(), paths: Vec::new(), dev: key.0, ino: key.1 });
                                        entry.size = child_own_size;
                                        entry.nlink = child_meta.nlink();
                                        entry.paths.push(entry_path_str.clone());
                                    }
                                    if dedup {
                                        let mut dup = 0u64;
                                        for inode_key in &child_inodes_set {
                                            if total_inodes_set.contains(inode_key) {
                                                if let Some(sz) = child_inode_sizes.get(inode_key) { dup += *sz; }
                                            }
                                        }
                                        total_size += child_total_size;
                                        total_size = total_size.saturating_sub(dup);
                                        for k in &child_inodes_set { total_inodes_set.insert(*k); }
                                        for (k,v) in child_inode_sizes.clone() { total_inode_sizes.entry(k).or_insert(v); }
                                    } else { total_size += child_total_size; }
                                    let child_node = BuildNode { name: entry_name, size: child_total_size, children: Vec::new(), inodes_set: child_inodes_set, inode_sizes: child_inode_sizes, own_size: child_own_size };
                                    children.push(child_node);
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    BuildNode { name, size: total_size, children, inodes_set: total_inodes_set, inode_sizes: total_inode_sizes, own_size }
}

fn build_for_path(input_path_str: &str, quantity: Quantity, dedup: bool, error_reporter: &ErrorReporter, global_hardlinks: &Arc<Mutex<HashMap<(u64, u64), HardlinkInfo>>>) -> BuildNode {
    let path = Path::new(input_path_str);
    match fs::symlink_metadata(path) {
        Err(e) => {
            error_reporter.report("symlink_metadata", input_path_str, &e);
            BuildNode { name: input_path_str.to_string(), size: 0, children: Vec::new(), inodes_set: HashSet::new(), inode_sizes: HashMap::new(), own_size: 0 }
        }
        Ok(meta) => {
            if is_dir_meta(&meta) {
                build_recursive(path, input_path_str.to_string(), quantity, dedup, error_reporter, global_hardlinks)
            } else {
                let own_size = quantity_size(&meta, quantity);
                let mut inodes_set = HashSet::new();
                let mut inode_sizes = HashMap::new();
                if dedup && meta.nlink() > 1 {
                    let key = (meta.dev(), meta.ino());
                    inodes_set.insert(key);
                    inode_sizes.insert(key, own_size);
                    let mut guard = global_hardlinks.lock().unwrap();
                    let entry = guard.entry(key).or_insert_with(|| HardlinkInfo { size: own_size, nlink: meta.nlink(), paths: Vec::new(), dev: key.0, ino: key.1 });
                    entry.size = own_size;
                    entry.nlink = meta.nlink();
                    entry.paths.push(input_path_str.to_string());
                }
                BuildNode { name: input_path_str.to_string(), size: own_size, children: Vec::new(), inodes_set, inode_sizes, own_size }
            }
        }
    }
}

fn build_forest(inputs: &[String], quantity: Quantity, dedup: bool, error_reporter: &ErrorReporter) -> (BuildNode, HashMap<(u64, u64), HardlinkInfo>) {
    let global_hardlinks: Arc<Mutex<HashMap<(u64, u64), HardlinkInfo>>> = Arc::new(Mutex::new(HashMap::new()));
    if inputs.is_empty() {
        let node = build_for_path(".", quantity, dedup, error_reporter, &global_hardlinks);
        let map = global_hardlinks.lock().unwrap().clone();
        (node, map)
    } else if inputs.len() == 1 {
        let node = build_for_path(&inputs[0], quantity, dedup, error_reporter, &global_hardlinks);
        let map = global_hardlinks.lock().unwrap().clone();
        (node, map)
    } else {
        let mut children = Vec::new();
        let mut total_inodes_set = HashSet::new();
        let mut total_inode_sizes = HashMap::new();
        let mut total_size = 0u64;
        for input in inputs {
            let child = build_for_path(input, quantity, dedup, error_reporter, &global_hardlinks);
            if dedup {
                let mut dup = 0u64;
                for inode_key in &child.inodes_set {
                    if total_inodes_set.contains(inode_key) {
                        if let Some(sz) = child.inode_sizes.get(inode_key).or_else(|| total_inode_sizes.get(inode_key)) { dup += *sz; }
                    }
                }
                total_size += child.size;
                total_size = total_size.saturating_sub(dup);
                for k in &child.inodes_set { total_inodes_set.insert(*k); }
                for (k,v) in &child.inode_sizes { total_inode_sizes.entry(*k).or_insert(*v); }
            } else { total_size += child.size; }
            children.push(child);
        }
        let root = BuildNode { name: "(total)".to_string(), size: total_size, children, inodes_set: total_inodes_set, inode_sizes: total_inode_sizes, own_size: 0 };
        let map = global_hardlinks.lock().unwrap().clone();
        (root, map)
    }
}

fn buildnode_to_treenode(b: &BuildNode, no_sort: bool) -> TreeNode {
    let mut children: Vec<TreeNode> = b.children.iter().map(|c| buildnode_to_treenode(c, no_sort)).collect();
    if !no_sort { children.sort_by(|a,b| b.size.cmp(&a.size)); }
    TreeNode { name: b.name.clone(), size: b.size, children }
}

