fn get_terminal_width(total_width: Option<usize>, _column_width: Option<&Vec<usize>>) -> usize {
    if let Some(tw) = total_width { return tw; }
    if let Ok(cols_str) = std::env::var("COLUMNS") { if let Ok(cols) = cols_str.parse::<usize>() { return cols; } }
    80
}

fn format_size(size: u64, fmt: BytesFormat, quantity: Quantity) -> String {
    match quantity { Quantity::BlockCount => { return size.to_string(); } _ => {} }
    match fmt {
        BytesFormat::Plain => size.to_string(),
        BytesFormat::Metric => format_metric(size),
        BytesFormat::Binary => format_binary(size),
    }
}
fn format_metric(size: u64) -> String {
    if size < 1000 { return size.to_string(); }
    let units = ["", "K", "M", "G", "T", "P", "E"];
    let mut val = size as f64;
    let mut idx = 0;
    while val >= 1000.0 && idx < units.len()-1 { val/=1000.0; idx+=1; }
    format!("{:.1}{}", val, units[idx])
}
fn format_binary(size: u64) -> String {
    if size < 1024 { return size.to_string(); }
    let units = ["", "K", "M", "G", "T", "P", "E"];
    let mut val = size as f64;
    let mut idx = 0;
    while val >= 1024.0 && idx < units.len()-1 { val/=1024.0; idx+=1; }
    format!("{:.1}{}", val, units[idx])
}
fn sort_tree_by_size(mut node: TreeNode) -> TreeNode {
    for child in &mut node.children { *child = sort_tree_by_size(child.clone()); }
    node.children.sort_by(|a,b| b.size.cmp(&a.size));
    node
}
fn filter_tree(node: TreeNode, visualizer: &Visualizer, total_size: u64, depth: usize) -> TreeNode {
    let mut filtered_children = Vec::new();
    if depth < visualizer.max_depth {
        for child in node.children {
            let ratio = if total_size==0 {0.0} else { child.size as f64 / total_size as f64 };
            if ratio < visualizer.min_ratio { continue; }
            filtered_children.push(filter_tree(child, visualizer, total_size, depth+1));
        }
        if !visualizer.no_sort { filtered_children.sort_by(|a,b| b.size.cmp(&a.size)); }
    }
    TreeNode { name: node.name, size: node.size, children: filtered_children }
}

struct Visualizer {
    bytes_format: BytesFormat,
    top_down: bool,
    align_right: bool,
    max_depth: usize,
    min_ratio: f64,
    no_sort: bool,
    column_width: Option<Vec<usize>>,
    total_width: Option<usize>,
    term_width: usize,
    quantity: Quantity,
}

impl Visualizer {
    fn visualize(&self, root: &TreeNode) -> String {
        // Simplified visualizer for now - just to make it compile
        // We will implement a basic version that produces similar output to original for simple cases
        // This placeholder will be replaced with full implementation later
        let mut result = String::new();

        // Collect nodes
        let mut ordered: Vec<(TreeNode, usize, Vec<bool>, bool, Vec<u64>)> = Vec::new();
        fn collect(node: &TreeNode, depth: usize, ancestors_last: Vec<bool>, is_last: bool, parent_sizes: Vec<u64>, ordered: &mut Vec<(TreeNode, usize, Vec<bool>, bool, Vec<u64>)>, top_down: bool) {
            if top_down {
                ordered.push((node.clone(), depth, ancestors_last.clone(), is_last, parent_sizes.clone()));
                for (idx, child) in node.children.iter().enumerate() {
                    let child_is_last = idx == node.children.len()-1;
                    let mut child_anc = ancestors_last.clone();
                    child_anc.push(is_last);
                    let mut child_par = parent_sizes.clone();
                    child_par.push(node.size);
                    collect(child, depth+1, child_anc, child_is_last, child_par, ordered, top_down);
                }
            } else {
                let mut children = node.children.clone();
                children.reverse();
                for (idx, child) in children.iter().enumerate() {
                    let child_is_first = idx == 0;
                    let mut child_anc = ancestors_last.clone();
                    child_anc.push(is_last);
                    let mut child_par = parent_sizes.clone();
                    child_par.push(node.size);
                    collect(child, depth+1, child_anc, child_is_first, child_par, ordered, top_down);
                }
                ordered.push((node.clone(), depth, ancestors_last, is_last, parent_sizes));
            }
        }
        collect(root, 1, Vec::new(), true, Vec::new(), &mut ordered, self.top_down);

        // For now, produce simple lines with size and name and fake bar
        // Determine bar width
        let term_width = self.term_width;
        // Compute max formatted size len
        let mut max_size_len = 0;
        let mut formatted_sizes: Vec<String> = Vec::new();
        for (node, _, _, _, _) in &ordered {
            let fs = format_size(node.size, self.bytes_format, self.quantity);
            max_size_len = max_size_len.max(fs.len());
            formatted_sizes.push(fs);
        }

        // Determine tree strings to compute tree width
        let mut tree_strings: Vec<String> = Vec::new();
        for (node, depth, ancestors_last, is_last, _) in &ordered {
            // Build tree string: ancestors prefix + connector + name
            let mut prefix = String::new();
            // ancestors_last contains bool for each ancestor level indicating if ancestor was last (or first for bottom-up? We'll use last flag for top-down, and for bottom-up we need different)
            // For simplicity, use same logic for both: if ancestor was last, then no vertical line, else "│ "
            // But need to skip root's ancestors?
            // For each ancestor level beyond root, add prefix
            for (i, &last) in ancestors_last.iter().enumerate() {
                if i == 0 { continue; } // root has no prefix?
                if last {
                    prefix.push_str("  ");
                } else {
                    prefix.push_str("│ ");
                }
            }
            let connector = if *depth == 1 {
                if node.children.is_empty() { "┌──" } else { "┌─┴" }
            } else {
                if self.top_down {
                    if *is_last {
                        if node.children.is_empty() { "└──" } else { "└─┬" }
                    } else {
                        if node.children.is_empty() { "├──" } else { "├─┬" }
                    }
                } else {
                    // bottom-up: first child uses ┌, others ├──
                    if *is_last { // in bottom-up we used is_last as is_first, so first child is_last true uses ┌
                        if node.children.is_empty() { "┌──" } else { "┌─┴" }
                    } else {
                        if node.children.is_empty() { "├──" } else { "├─┴" }
                    }
                }
            };
            let tree = format!("{}{}{}", prefix, connector, node.name);
            tree_strings.push(tree);
        }

        let max_tree_len = tree_strings.iter().map(|s| s.chars().count()).max().unwrap_or(0);

        // Determine bar width
        let bar_width = if let Some(cw) = &self.column_width {
            cw[1]
        } else {
            // total_width = size_width + tree_width + bar_width + percent_width + 2
            // size_width = max_size_len + 3 (for child) maybe? Let's approximate as max_size_len + 3
            let size_width = max_size_len + 3;
            let percent_width = 4; // e.g., "100%" len 4
            // tree_width = max_tree_len (maybe limited)
            let tree_width = max_tree_len;
            if term_width > size_width + tree_width + percent_width + 2 {
                term_width - size_width - tree_width - percent_width - 2
            } else {
                10
            }
        };

        let tree_width = if let Some(cw) = &self.column_width {
            cw[0]
        } else {
            max_tree_len
        };

        // Now produce lines
        for (idx, ((node, _depth, _anc, _is_last, parent_sizes), tree_str)) in ordered.iter().zip(tree_strings.iter()).enumerate() {
            let formatted_size = &formatted_sizes[idx];
            // size field: right-aligned in max_size_len + padding?
            // For bottom-up, size field width = max_size_len + 3 for non-root, +1 for root?
            // For simplicity, use max_size_len + 3 for all except root maybe
            let is_root = idx == ordered.len()-1 && !self.top_down || idx==0 && self.top_down;
            let size_field = if is_root {
                format!("{:>width$} ", formatted_size, width=max_size_len)
            } else {
                format!("{:>width$}   ", formatted_size, width=max_size_len)
            };

            // tree field: need to truncate or pad to tree_width
            let mut tree_field = tree_str.clone();
            // Truncate if exceeds tree_width
            let tree_len = tree_field.chars().count();
            if tree_len > tree_width {
                // truncate with "..."
                if tree_width >= 3 {
                    let truncated: String = tree_field.chars().take(tree_width-3).collect();
                    tree_field = format!("{}...", truncated);
                } else {
                    tree_field = tree_field.chars().take(tree_width).collect();
                }
            } else {
                // pad with spaces
                let pad = tree_width - tree_len;
                tree_field.push_str(&" ".repeat(pad));
            }

            // bar: compute based on size / total
            let total = root.size;
            let proportion = if total==0 { 0.0 } else { node.size as f64 / total as f64 };
            let mut filled = (proportion * bar_width as f64).round() as usize;
