}

fn get_terminal_width(total_width: Option<usize>, _column_width: Option<&Vec<usize>>) -> usize {
    if let Some(tw) = total_width { return tw; }
    if let Ok(cols_str) = std::env::var("COLUMNS") { if let Ok(cols) = cols_str.parse::<usize>() { return cols; } }
    80
}

fn format_size(size: u64, fmt: BytesFormat, quantity: Quantity) -> String {
    match quantity { Quantity::BlockCount => { return size.to_string(); } _ => {} }
    match fmt {
        BytesFormat::Plain => size.to_string(),
        BytesFormat::Metric => format_metric(size),
        BytesFormat::Binary => format_binary(size),
    }
}
fn format_metric(size: u64) -> String {
    if size < 1000 { return size.to_string(); }
    let units = ["", "K", "M", "G", "T", "P", "E"];
    let mut val = size as f64;
    let mut idx = 0;
    while val >= 1000.0 && idx < units.len()-1 { val/=1000.0; idx+=1; }
    format!("{:.1}{}", val, units[idx])
}
fn format_binary(size: u64) -> String {
    if size < 1024 { return size.to_string(); }
    let units = ["", "K", "M", "G", "T", "P", "E"];
    let mut val = size as f64;
    let mut idx = 0;
    while val >= 1024.0 && idx < units.len()-1 { val/=1024.0; idx+=1; }
    format!("{:.1}{}", val, units[idx])
}
fn sort_tree_by_size(mut node: TreeNode) -> TreeNode {
    for child in &mut node.children { *child = sort_tree_by_size(child.clone()); }
    node.children.sort_by(|a,b| b.size.cmp(&a.size));
    node
}
fn filter_tree(node: TreeNode, visualizer: &Visualizer, total_size: u64, depth: usize) -> TreeNode {
    let mut filtered_children = Vec::new();
    if depth < visualizer.max_depth {
        for child in node.children {
            let ratio = if total_size==0 {0.0} else { child.size as f64 / total_size as f64 };
            if ratio < visualizer.min_ratio { continue; }
            filtered_children.push(filter_tree(child, visualizer, total_size, depth+1));
        }
        if !visualizer.no_sort { filtered_children.sort_by(|a,b| b.size.cmp(&a.size)); }
    }
    TreeNode { name: node.name, size: node.size, children: filtered_children }
}

struct Visualizer {
    bytes_format: BytesFormat,
    top_down: bool,
    align_right: bool,
    max_depth: usize,
    min_ratio: f64,
    no_sort: bool,
    column_width: Option<Vec<usize>>,
    total_width: Option<usize>,
    term_width: usize,
    quantity: Quantity,
}

impl Visualizer {
    fn visualize(&self, root: &TreeNode) -> String {
        // Very simplified bar: only █, no ░▒ handling for now, but we will try to implement at least basic bar with █ and spaces.
        // This will not fully match original, but we can improve later.
        // Steps:
        // - Collect nodes in display order
        // - Compute tree strings
        // - Compute bar widths

        let mut ordered: Vec<(TreeNode, usize, Vec<bool>, bool)> = Vec::new();
        fn collect(node: &TreeNode, depth: usize, anc_last: Vec<bool>, is_last: bool, ordered: &mut Vec<(TreeNode, usize, Vec<bool>, bool)>, top_down: bool) {
            if top_down {
                ordered.push((node.clone(), depth, anc_last.clone(), is_last));
                for (idx, child) in node.children.iter().enumerate() {
                    let child_is_last = idx == node.children.len()-1;
                    let mut child_anc = anc_last.clone();
                    child_anc.push(is_last);
                    collect(child, depth+1, child_anc, child_is_last, ordered, top_down);
                }
            } else {
                let mut children = node.children.clone();
                children.reverse();
                for child in children.iter() {
                    let mut child_anc = anc_last.clone();
                    child_anc.push(is_last);
                    collect(child, depth+1, child_anc, false, ordered, top_down);
                }
                ordered.push((node.clone(), depth, anc_last, is_last));
            }
        }
        collect(root, 1, Vec::new(), true, &mut ordered, self.top_down);

        // Compute formatted sizes
        let mut max_size_len = 0;
        let mut formatted: Vec<String> = Vec::new();
        for (node, _, _, _) in &ordered {
            let f = format_size(node.size, self.bytes_format, self.quantity);
            max_size_len = max_size_len.max(f.len());
            formatted.push(f);
        }

        // Compute tree strings
        let mut tree_strs: Vec<String> = Vec::new();
        for (node, depth, anc_last, _is_last) in &ordered {
            let mut prefix = String::new();
            for (i, &last) in anc_last.iter().enumerate() {
                if i==0 { continue; }
                if last { prefix.push_str("  "); } else { prefix.push_str("│ "); }
            }
            let connector = if *depth==1 {
                if node.children.is_empty() { "┌──" } else { "┌─┴" }
            } else {
                if self.top_down {
                    if *_is_last {
                        if node.children.is_empty() { "└──" } else { "└─┬" }
                    } else {
                        if node.children.is_empty() { "├──" } else { "├─┬" }
                    }
                } else {
                    // bottom-up: first child uses ┌, others ├──. For simplicity, use ┌ for first, ├ for rest.
                    // Since in bottom-up ordered, first child is topmost, we need to know if it's first among siblings.
                    // Our collect for bottom-up sets is_last false for all, so we cannot distinguish. Let's use depth and anc?
                    // We'll use simple: if anc_last indicates something? For bottom-up, topmost child should have ┌, others ├.
                    // Since we reversed children, the first in reversed order is smallest (topmost). So for bottom-up, the first visited child is topmost.
                    // We set is_last false always, so we need better tracking.
                    // For now, use "┌──" for all leaves? This is simplified.
                    if node.children.is_empty() { "┌──" } else { "┌─┴" }
                }
            };
            let s = format!("{}{}{}", prefix, connector, node.name);
            tree_strs.push(s);
        }

        let max_tree_len = tree_strs.iter().map(|s| s.chars().count()).max().unwrap_or(0);
        let tree_width = if let Some(cw) = &self.column_width { cw[0] } else { max_tree_len };
        let bar_width = if let Some(cw) = &self.column_width { cw[1] } else {
            let size_width = max_size_len + 3;
            let percent_width = 4;
            if self.term_width > size_width + tree_width + percent_width + 2 {
                self.term_width - size_width - tree_width - percent_width - 2
            } else { 10 }
        };

        let mut out = String::new();
        for (i, ((node, _, _, _), tree_str)) in ordered.iter().zip(tree_strs.iter()).enumerate() {
            let fsize = &formatted[i];
            let is_root = if self.top_down { i==0 } else { i==ordered.len()-1 };
            let size_field = if is_root {
                format!("{:>width$} ", fsize, width=max_size_len)
            } else {
                format!("{:>width$}   ", fsize, width=max_size_len)
            };
            // tree field truncated/padded
            let mut tree_field = tree_str.clone();
            let tlen = tree_field.chars().count();
            if tlen > tree_width {
                if tree_width>=3 {
                    let trunc: String = tree_field.chars().take(tree_width-3).collect();
                    tree_field = format!("{}...", trunc);
                } else {
                    tree_field = tree_field.chars().take(tree_width).collect();
                }
            } else {
                tree_field.push_str(&" ".repeat(tree_width - tlen));
            }

            // bar
            let total = root.size;
            let prop = if total==0 { 0.0 } else { node.size as f64 / total as f64 };
            let filled = (prop * bar_width as f64).round() as usize;
            let filled = std::cmp::min(filled, bar_width);
            let mut bar = String::new();
            if self.align_right {
                let empty = bar_width - filled;
                bar.push_str(&" ".repeat(empty));
                bar.push_str(&"█".repeat(filled));
            } else {
                bar.push_str(&"█".repeat(filled));
                bar.push_str(&" ".repeat(bar_width - filled));
            }

            // percent
            let pct = if total==0 { 0 } else { ((node.size as f64 / total as f64)*100.0).round() as usize };
            let pct_str = format!("{:>3}%", pct);

            out.push_str(&format!("{}{}│{}│{}\n", size_field, tree_field, bar, pct_str));
        }
        out
    }
}

fn main() {
    let cmd = build_cli_command();
    let matches = match cmd.try_get_matches() {
        Ok(m) => m,
        Err(e) => { e.exit(); }
    };

    let json_input = matches.get_flag("json_input");
    let json_output = matches.get_flag("json_output");
    let deduplicate = matches.get_flag("deduplicate_hardlinks");
    let top_down = matches.get_flag("top_down");
    let align_right = matches.get_flag("align_right");
    let no_sort = matches.get_flag("no_sort");
    let silent_errors = matches.get_flag("silent_errors");
    let progress = matches.get_flag("progress");
    let omit_details = matches.get_flag("omit_json_shared_details");
    let omit_summary = matches.get_flag("omit_json_shared_summary");

    let bytes_format_str = matches.get_one::<String>("bytes_format").unwrap().as_str();
    let bytes_format = match bytes_format_str {
        "plain" => BytesFormat::Plain,
        "metric" => BytesFormat::Metric,
        "binary" => BytesFormat::Binary,
        _ => BytesFormat::Metric,
    };
    let quantity_str = matches.get_one::<String>("quantity").unwrap().as_str();
    let quantity = match quantity_str {
        "apparent-size" => Quantity::ApparentSize,
        "block-size" => Quantity::BlockSize,
        "block-count" => Quantity::BlockCount,
        _ => Quantity::BlockSize,
    };
    let max_depth_str = matches.get_one::<String>("max_depth").unwrap().as_str();
    let max_depth = match parse_max_depth(max_depth_str) {
        Ok(md) => md,
        Err(msg) => {
            eprintln!("error: invalid value '{}' for '--max-depth <MAX_DEPTH>': {}", max_depth_str, msg);
            eprintln!();
            eprintln!("For more information, try '--help'.");
            std::process::exit(2);
        }
    };
    let total_width = match matches.get_one::<String>("total_width") {
        Some(s) => match parse_total_width(s) {
