        Ok(v) => {
            if v < 0.0 { Err("less than 0".to_string()) }
            else if v >= 1.0 { Err("greater than or equal to 1".to_string()) }
            else { Ok(v) }
        }
        Err(_) => Err("invalid float literal".to_string()),
    }
}
fn parse_total_width(s: &str) -> Result<usize, String> {
    let s = s.trim();
    if s.is_empty() { return Err("cannot parse integer from empty string".to_string()); }
    match s.parse::<usize>() {
        Ok(v) => Ok(v),
        Err(e) => {
            let msg = e.to_string();
            if msg.contains("invalid digit") { Err("invalid digit found in string".to_string()) }
            else if msg.contains("too large") { Err("number too large to fit in target type".to_string()) }
            else { Err(msg) }
        }
    }
}
