    } else {
        let term_width = get_terminal_width(total_width, column_width.as_ref());
        let visualizer = Visualizer {
            bytes_format,
            top_down,
            align_right,
            max_depth: match max_depth { MaxDepth::Inf => usize::MAX, MaxDepth::Finite(d) => d },
            min_ratio,
            no_sort,
            column_width: column_width.clone(),
            total_width,
            term_width,
            quantity,
        };
        let total_size = root_build.size;
        let filtered_tree = filter_tree(tree_node, &visualizer, total_size, 1);
        let output = visualizer.visualize(&filtered_tree);
        print!("{}", output);
        if !hardlink_map.is_empty() && deduplicate {
            let mut inodes = 0;
            let mut exclusive_inodes = 0;
            let mut all_links = 0;
            let mut detected_links = 0;
            let mut exclusive_links = 0;
            let mut shared_size = 0;
            let mut exclusive_shared_size = 0;
            for (_, info) in hardlink_map.iter() {
                inodes += 1;
                all_links += info.nlink as usize;
                detected_links += info.paths.len();
                shared_size += info.size;
                let is_exclusive = info.paths.len() as u64 == info.nlink;
                if is_exclusive {
                    exclusive_inodes += 1;
                    exclusive_links += info.paths.len();
                    exclusive_shared_size += info.size;
                }
            }
            let formatted_shared_size = format_size(shared_size, bytes_format, quantity);
            let formatted_exclusive_shared_size = format_size(exclusive_shared_size, bytes_format, quantity);
            if exclusive_inodes == inodes {
                println!("Hardlinks detected! No files have links outside this tree");
